```python file=solution.py
from math import isqrt


def _is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    for divisor in range(3, isqrt(n) + 1, 2):
        if n % divisor == 0:
            return False
    return True


def solve(value):
    return [_is_prime(n) for n in value]
```

